with deduped as (select *, row_number() over (partition by status order by delivered_date nulls first, id) as rank_in_group from shipments qualify rank_in_group = 1) select case when cost >= 89 then 'LARGE' else 'SMALL' end as cost_tier, round(sum(cost) / nullif(count(case when status = 'RETURNED' then 1 end), 0), 2) as cost_per_returned, round(avg(cost), 2) as avg_cost, stddev_samp(cost) as cost_stddev, size(collect_set(carrier)) as num_carriers, round(sum(cost) / nullif(count(case when carrier = 'FedEx' then 1 end), 0), 2) as cost_per_fedex from deduped group by case when cost >= 89 then 'LARGE' else 'SMALL' end having num_carriers > 1 order by cost_tier nulls last;
